export const inject=['uiSession','slots'];
function FilmIcon({size=20}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4zM3 8h3M3 16h3M18 8h3M18 16h3"/></svg>}
export function apply(ctx){bindPromptSession(ctx);ctx.slots.inject('main',()=>ctx.slots.register({name:'main',key:'live-film'},FilmApp));connectLaunchpad(ctx,service=>{taskServiceRef.current=service;const remove=service.registerApp({id:'live-film',name:'镜头工坊',description:'规划镜头、管理参考素材与视频生成任务。',icon:FilmIcon,order:30});return()=>{remove();taskServiceRef.current=null}},'live-film')}
